import{_ as a,o as t,c as l,a2 as o}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"传感器与时间同步","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/sensors-and-time.md","filePath":"knowledge/sensors-and-time.md","lastUpdated":1787217884000}'),i={name:"knowledge/sensors-and-time.md"};function r(n,e,s,d,c,h){return t(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="传感器与时间同步" tabindex="-1">传感器与时间同步 <a class="header-anchor" href="#传感器与时间同步" aria-label="Permalink to &quot;传感器与时间同步&quot;">​</a></h1><p><strong>状态：</strong> <code>设计建议</code> · <strong>适用范围：</strong> 多传感器自动驾驶链路</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li>传感器消息频率正常，但融合目标出现拖影或跳动。</li><li>回放时结果稳定，在线运行时不稳定。</li><li>不同设备的时间戳看似都是 Unix 时间，却无法对齐。</li></ul><h2 id="排查顺序" tabindex="-1">排查顺序 <a class="header-anchor" href="#排查顺序" aria-label="Permalink to &quot;排查顺序&quot;">​</a></h2><ol><li>记录每条消息的采集时间、发布时间、接收时间和序列号，不要只看 ROS/中间件的一个时间字段。</li><li>计算相邻消息周期、延迟分布和跨传感器时间差，观察均值之外的长尾。</li><li>确认所有设备使用的时钟源、同步协议和时区/单调时钟语义。</li><li>在固定数据集上回放，逐步改变时间偏移，确认算法对误差的敏感度。</li><li>记录同步修正前后的指标，并保留失败样本。</li></ol><h2 id="不应直接下的结论" tabindex="-1">不应直接下的结论 <a class="header-anchor" href="#不应直接下的结论" aria-label="Permalink to &quot;不应直接下的结论&quot;">​</a></h2><p>“时间同步解决了”至少需要一个可复现的环境、偏移量、修正方法和指标。当前 WheelOS 仓库路线图提到传感器时间同步工具，但本页不把路线图当作实现或实车验证证据。</p>',8)])])}const p=a(i,[["render",r]]);export{m as __pageData,p as default};
